```javascript
const sessions = new Map();

const tools = [
  {
    name: 'begin_session',
    description: 'Begin a new isolated session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string', minLength: 1 }
      },
      required: ['session_id'],
      additionalProperties: false
    }
  },
  {
    name: 'put_value',
    description: 'Store a value for a key in a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string', minLength: 1 },
        key: { type: 'string', minLength: 1 },
        value: { type: 'string' }
      },
      required: ['session_id', 'key', 'value'],
      additionalProperties: false
    }
  },
  {
    name: 'get_value',
    description: 'Retrieve a value for a key from a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string', minLength: 1 },
        key: { type: 'string', minLength: 1 }
      },
      required: ['session_id', 'key'],
      additionalProperties: false
    }
  }
];

function validate(name, args) {
  const tool = tools.find(t => t.name === name);
  if (!tool) throw new Error('Unknown tool: ' + name);
  const schema = tool.inputSchema;
  // check required
  for (const r of schema.required) {
    if (!(r in args)) throw new Error('Missing argument: ' + r);
  }
  // check extra
  for (const k of Object.keys(args)) {
    if (!(k in schema.properties)) throw new Error('Unknown argument: ' + k);
  }
  // check types
  for (const [k, v] of Object.entries(args)) {
    const prop = schema.properties[k];
    if (prop.type === 'string') {
      if (typeof v !== 'string') throw new Error('Argument must be string: ' + k);
      if (prop.minLength !== undefined && v.length < prop.minLength) throw new Error('Argument must be non-empty: ' + k);
    }
  }
}

export async function listTools() {
  return tools;
}

export async function callTool(name, args = {}) {
  validate(name, args);
  if (name === 'begin_session') {
    const { session_id } = args;
    if (!sessions.has(session_id)) sessions.set(session_id, new Map());
    return { content: [{ type: 'text', text: session_id }] };
  }
  if (name === 'put_value') {
    const { session_id, key, value } = args;
    if (!sessions.has(session_id)) throw new Error('Session not found: ' + session_id);
    sessions.get(session_id).set(key, value);
    return { content: [{ type: 'text', text: 'ok' }] };
  }
  if (name === 'get_value') {
    const { session_id, key } = args;
    if (!sessions.has(session_id)) throw new Error('Session not found: ' + session_id);
    const store = sessions.get(session_id);
    if (!store.has(key)) throw new Error('Key not found: ' + key);
    return { content: [{ type: 'text', text: store.get(key) }] };
  }
  throw new Error('Unknown tool: ' + name);
}
